using Microsoft.Data.Sqlite;
var builder=WebApplication.CreateBuilder(args);var app=builder.Build();var adminSecret=Environment.GetEnvironmentVariable("AYGEST_ADMIN_SECRET")??"";var dbPath=Path.Combine(AppContext.BaseDirectory,"aygest-server.db");
using(var c=new SqliteConnection($"Data Source={dbPath}")){c.Open();using var q=c.CreateCommand();q.CommandText="CREATE TABLE IF NOT EXISTS tenants(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS licenses(key_value TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,plan TEXT NOT NULL,expires_at TEXT,active INTEGER NOT NULL DEFAULT 1,device_id TEXT);CREATE TABLE IF NOT EXISTS sync_events(id INTEGER PRIMARY KEY AUTOINCREMENT,tenant_id TEXT NOT NULL,event_id TEXT NOT NULL UNIQUE,event_type TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS idx_sync_tenant_id ON sync_events(tenant_id,id);";q.ExecuteNonQuery();}
app.MapGet("/health",()=>Results.Ok(new{status="ok",service="AyGest Server",utc=DateTime.UtcNow}));
app.MapPost("/api/v1/licenses/activate",async(HttpRequest req)=>{var body=await System.Text.Json.JsonSerializer.DeserializeAsync<ActivationRequest>(req.Body);if(body is null||string.IsNullOrWhiteSpace(body.Key))return Results.BadRequest(new{active=false,message="Activation Key obrigatória."});using var c=new SqliteConnection($"Data Source={dbPath}");c.Open();using var q=c.CreateCommand();q.CommandText="SELECT tenant_id,plan,expires_at,active FROM licenses WHERE key_value=@k";q.Parameters.AddWithValue("@k",body.Key.Trim().ToUpperInvariant());using var r=q.ExecuteReader();if(!r.Read())return Results.NotFound(new{active=false,message="Activation Key não encontrada."});var tenant=r.GetString(0);var plan=r.GetString(1);var exp=r.IsDBNull(2)?null:r.GetString(2);var active=r.GetInt32(3)==1;if(!active)return Results.Ok(new{active=false,message="Licença revogada."});if(DateTime.TryParse(exp,out var dt)&&dt.ToUniversalTime()<DateTime.UtcNow)return Results.Ok(new{active=false,message="Licença expirada."});r.Close();q.Parameters.Clear();q.CommandText="UPDATE licenses SET device_id=@d WHERE key_value=@k";q.Parameters.AddWithValue("@d",body.DeviceId??"");q.Parameters.AddWithValue("@k",body.Key.Trim().ToUpperInvariant());q.ExecuteNonQuery();return Results.Ok(new{active=true,key=body.Key.Trim().ToUpperInvariant(),tenant_id=tenant,plan,expires_at=exp});});
app.MapPost("/api/v1/licenses/verify",async(HttpRequest req)=>{var body=await System.Text.Json.JsonSerializer.DeserializeAsync<ActivationRequest>(req.Body);if(body is null)return Results.BadRequest();using var c=new SqliteConnection($"Data Source={dbPath}");c.Open();using var q=c.CreateCommand();q.CommandText="SELECT tenant_id,plan,expires_at,active,device_id FROM licenses WHERE key_value=@k";q.Parameters.AddWithValue("@k",body.Key?.Trim().ToUpperInvariant()??"");using var r=q.ExecuteReader();if(!r.Read())return Results.NotFound(new{active=false,message="Licença não encontrada."});var active=r.GetInt32(3)==1;var exp=r.IsDBNull(2)?null:r.GetString(2);var device=r.IsDBNull(4)?null:r.GetString(4);if(DateTime.TryParse(exp,out var dt)&&dt.ToUniversalTime()<DateTime.UtcNow)active=false;if(!string.IsNullOrWhiteSpace(device)&&device!=body.DeviceId)active=false;return Results.Ok(new{active,key=body.Key,tenant_id=r.GetString(0),plan=r.GetString(1),expires_at=exp,message=active?"Licença válida.":"Licença inválida."});});
app.MapPost("/api/v1/admin/licenses",async(HttpRequest req)=>{if(string.IsNullOrWhiteSpace(adminSecret)||!req.Headers.TryGetValue("X-AyGest-Admin",out var supplied)||supplied!=adminSecret)return Results.Unauthorized();var body=await System.Text.Json.JsonSerializer.DeserializeAsync<CreateLicenseRequest>(req.Body);if(body is null||string.IsNullOrWhiteSpace(body.Key)||string.IsNullOrWhiteSpace(body.TenantId))return Results.BadRequest();using var c=new SqliteConnection($"Data Source={dbPath}");c.Open();using var q=c.CreateCommand();q.CommandText="INSERT OR REPLACE INTO tenants(id,name,created_at) VALUES(@t,@n,@d);INSERT OR REPLACE INTO licenses(key_value,tenant_id,plan,expires_at,active) VALUES(@k,@t,@p,@e,1)";q.Parameters.AddWithValue("@t",body.TenantId);q.Parameters.AddWithValue("@n",body.TenantName??body.TenantId);q.Parameters.AddWithValue("@d",DateTime.UtcNow.ToString("O"));q.Parameters.AddWithValue("@k",body.Key.Trim().ToUpperInvariant());q.Parameters.AddWithValue("@p",body.Plan??"Standard");q.Parameters.AddWithValue("@e",(object?)body.ExpiresAt??DBNull.Value);q.ExecuteNonQuery();return Results.Ok(new{created=true,key=body.Key.Trim().ToUpperInvariant(),tenant_id=body.TenantId,plan=body.Plan??"Standard",expires_at=body.ExpiresAt});});
static bool LicenseAllowed(SqliteConnection c,string key,string tenant,string device){using var q=c.CreateCommand();q.CommandText="SELECT tenant_id,expires_at,active,device_id FROM licenses WHERE key_value=@k";q.Parameters.AddWithValue("@k",key.Trim().ToUpperInvariant());using var r=q.ExecuteReader();if(!r.Read()||r.GetString(0)!=tenant||r.GetInt32(2)!=1)return false;var exp=r.IsDBNull(1)?null:r.GetString(1);var stored=r.IsDBNull(3)?null:r.GetString(3);if(DateTime.TryParse(exp,out var dt)&&dt.ToUniversalTime()<DateTime.UtcNow)return false;return string.IsNullOrWhiteSpace(stored)||stored==device;}
app.MapPost("/api/v1/sync/events",async(HttpRequest req)=>{var body=await System.Text.Json.JsonSerializer.DeserializeAsync<SyncEventRequest>(req.Body);if(body is null||string.IsNullOrWhiteSpace(body.TenantId)||string.IsNullOrWhiteSpace(body.EventId)||string.IsNullOrWhiteSpace(body.EventType)||string.IsNullOrWhiteSpace(body.LicenseKey)||string.IsNullOrWhiteSpace(body.DeviceId))return Results.BadRequest(new{ok=false,message="Dados de sincronização incompletos."});using var c=new SqliteConnection($"Data Source={dbPath}");c.Open();if(!LicenseAllowed(c,body.LicenseKey,body.TenantId,body.DeviceId))return Results.Unauthorized();using var q=c.CreateCommand();q.CommandText="INSERT OR IGNORE INTO sync_events(tenant_id,event_id,event_type,payload,created_at) VALUES(@t,@i,@e,@p,@d)";q.Parameters.AddWithValue("@t",body.TenantId);q.Parameters.AddWithValue("@i",body.EventId);q.Parameters.AddWithValue("@e",body.EventType);q.Parameters.AddWithValue("@p",body.Payload.GetRawText());q.Parameters.AddWithValue("@d",DateTime.UtcNow.ToString("O"));q.ExecuteNonQuery();return Results.Ok(new{ok=true,event_id=body.EventId});});
app.MapGet("/api/v1/sync/events",(string tenantId,long afterId=0,int limit=500,string licenseKey="",string deviceId="")=>{limit=Math.Clamp(limit,1,1000);using var c=new SqliteConnection($"Data Source={dbPath}");c.Open();if(!LicenseAllowed(c,licenseKey,tenantId,deviceId))return Results.Unauthorized();using var q=c.CreateCommand();q.CommandText="SELECT id,event_id,event_type,payload,created_at FROM sync_events WHERE tenant_id=@t AND id>@i ORDER BY id LIMIT @l";q.Parameters.AddWithValue("@t",tenantId);q.Parameters.AddWithValue("@i",afterId);q.Parameters.AddWithValue("@l",limit);using var r=q.ExecuteReader();var events=new List<object>();while(r.Read())events.Add(new{id=r.GetInt64(0),event_id=r.GetString(1),event_type=r.GetString(2),payload=r.GetString(3),created_at=r.GetString(4)});return Results.Ok(new{tenant_id=tenantId,events});});
app.Run();
record ActivationRequest(string? Key,string? TenantId,string? DeviceId);record CreateLicenseRequest(string Key,string TenantId,string? TenantName,string? Plan,string? ExpiresAt);record SyncEventRequest(string TenantId,string EventId,string EventType,System.Text.Json.JsonElement Payload,string LicenseKey,string DeviceId);